// Executes the pure geometry of the lighting lane outside Unity (managed math only).
using System;
using System.Reflection;
using UnityEngine;
using Doppel6.Probe;
static class Harness {
    static Vector3 Forward(float pitch,float yaw){float p=pitch*Mathf.Deg2Rad,y=yaw*Mathf.Deg2Rad;return new Vector3(Mathf.Sin(y)*Mathf.Cos(p),-Mathf.Sin(p),Mathf.Cos(y)*Mathf.Cos(p));}
    static int Main(){
        var t=typeof(MatchLightingTests);var flags=BindingFlags.NonPublic|BindingFlags.Static;
        float Far(float l,float w)=>(float)t.GetMethod("FarCorner",flags).Invoke(null,new object[]{l,w});
        float corner=Far(68,44),large=Far(81.6f,52.8f),full=1-MatchLighting.ShadowFade;
        float reach=MatchLighting.ShadowDistance(68,44),largeReach=MatchLighting.ShadowDistance(81.6f,52.8f);
        Console.WriteLine($"farCorner 68x44={corner:0.000} reach={reach:0.000} full={reach*full:0.000} need>={corner+5-.05f:0.000} <= {corner+6.5f:0.000}");
        Console.WriteLine($"farCorner 81.6x52.8={large:0.000} reach={largeReach:0.000} full={largeReach*full:0.000} need>={large+5-.05f:0.000} <= {large+6.5f:0.000}");
        bool ok=reach*full>=corner+5-.05f&&reach*full<=corner+6.5f&&largeReach*full>=large+5-.05f&&largeReach*full<=large+6.5f&&reach<110;
        // Day sun Euler(55,135,0): shadows away from all five cameras.
        var f=Forward(55,135);var way=new Vector2(f.x,f.z).normalized;float least=1;string worst="";
        var aim=t.GetMethod("Aim",flags);
        foreach(var mode in new[]{"follow","wide","sideline","diagonal","goal"})for(int i=0;i<=8;i++)for(int j=0;j<=4;j++){
            var ball=new Vector3((i/8f-.5f)*68,0,(j/4f-.5f)*44);var pt=((Vector3,Vector3))aim.Invoke(null,new object[]{mode,ball});
            float d=Vector2.Dot(new Vector2(pt.Item2.x-pt.Item1.x,pt.Item2.z-pt.Item1.z).normalized,way);if(d<least){least=d;worst=mode+" "+ball;}}
        float elevation=Mathf.Asin(-f.y)*Mathf.Rad2Deg;
        Console.WriteLine($"day forward=({f.x:0.000},{f.y:0.000},{f.z:0.000}) elevation={elevation:0.00} leastAway={least:0.000} at {worst}");
        ok&=least>0&&elevation>=50&&elevation<=60;
        // Night key Euler(54,-32,0) for reference (Release 130).
        var n=Forward(54,-32);Console.WriteLine($"night forward=({n.x:0.000},{n.y:0.000},{n.z:0.000})");
        Console.WriteLine(ok?"HARNESS OK":"HARNESS FAILED");return ok?0:1;
    }
}

