'use strict';
// Syntax/type check of the D6 shader programs the way Unity's D3D11 path does:
// preprocess (DXC's clang preprocessor, as Unity preprocesses itself), then FXC
// with the backwards-compatibility flag, against copies of the URP/Core 17.6
// shader libraries. Prints failures and the set of compiler warnings.
//   node shadercheck.cjs <scratch> <shader source folder>
const fs=require('node:fs'),path=require('node:path'),{spawnSync}=require('node:child_process');
const [scratch,source]=process.argv.slice(2);
const dxc='C:/Program Files (x86)/Windows Kits/10/bin/10.0.19041.0/x64/dxc.exe';
const fxc='C:/Program Files (x86)/Windows Kits/10/bin/10.0.19041.0/x64/fxc.exe';
const root=path.join(scratch,'hlsl'),art=path.join(root,'Art'),res=path.join(art,'Resources');
fs.copyFileSync(path.join(source,'D6Common.hlsl'),path.join(art,'D6Common.hlsl'));
const shaders={'WorldKit.shader':art,'D6Pitch.shader':res,'D6Blob.shader':res,'D6Env.shader':res,'D6TeamRing.shader':res};
const variants=[[],['_MAIN_LIGHT_SHADOWS'],['_MAIN_LIGHT_SHADOWS','_SHADOWS_SOFT'],['_MAIN_LIGHT_SHADOWS','_SHADOWS_SOFT_MEDIUM'],['_MAIN_LIGHT_SHADOWS_CASCADE','_SHADOWS_SOFT_LOW']];
let failures=0,compiled=0;const warnings=new Set();
for(const [name,folder] of Object.entries(shaders)){
  const text=fs.readFileSync(path.join(source,name),'utf8');
  const include=(text.match(/HLSLINCLUDE([\s\S]*?)ENDHLSL/)||[,''])[1];
  const programs=[...text.matchAll(/HLSLPROGRAM([\s\S]*?)ENDHLSL/g)].map(m=>m[1]);
  programs.forEach((program,index)=>{
    const vertex=(program.match(/#pragma\s+vertex\s+(\w+)/)||[])[1],fragment=(program.match(/#pragma\s+fragment\s+(\w+)/)||[])[1];
    const body=program.replace(/^\s*#pragma.*$/mg,'');
    for(const keys of variants)for(const [stage,entry,profile] of [['VERTEX',vertex,'vs_5_0'],['FRAGMENT',fragment,'ps_5_0']]){
      if(!entry)continue;
      const file=path.join(folder,`check-${name.replace('.shader','')}-${index}.hlsl`),pre=file.replace(/\.hlsl$/,'.pre.hlsl');
      const defines=['SHADER_API_D3D11 1','SHADER_TARGET 35','UNITY_VERSION 600060',`SHADER_STAGE_${stage} 1`,...keys.map(k=>k+' 1')].map(d=>'#define '+d);
      fs.writeFileSync(file,defines.join('\n')+'\n'+include+'\n'+body);
      let r=spawnSync(dxc,['-P',pre,'-I',root,file],{encoding:'utf8'});
      if(r.status===0)r=spawnSync(fxc,['/nologo','/Gec','/T',profile,'/E',entry,'/Fo',path.join(scratch,'out.dxbc'),pre],{encoding:'utf8'});
      compiled++;
      const lines=((r.stderr||'')+(r.stdout||'')).split(/\r?\n/);
      if(r.status!==0){failures++;console.log(`FAIL ${name} pass ${index} ${stage} [${keys.join(' ')}]\n`+lines.filter(l=>/error/i.test(l)).slice(0,8).join('\n'));}
      else for(const l of lines)if(/warning/i.test(l)&&!/Packages[\\/]/.test(l))warnings.add(`${name} ${stage} ${l.replace(/^.*\.pre\.hlsl/,'')}`.trim());
    }
  });
}
for(const w of [...warnings].sort())console.log('WARN '+w);
console.log(`compiled ${compiled} stage/variant programs, failures ${failures}`);process.exit(failures?1:0);

