'use strict';
// Legacy exactness: the modified shaders without _D6_LOOK must compile to the
// same FXC program as the HEAD shaders, for every stage and shadow variant.
//   node legacycheck.cjs <scratch> <head source folder> <modified source folder>
const fs=require('node:fs'),path=require('node:path'),{spawnSync}=require('node:child_process');
const [scratch,head,modified]=process.argv.slice(2);
const dxc='C:/Program Files (x86)/Windows Kits/10/bin/10.0.19041.0/x64/dxc.exe';
const fxc='C:/Program Files (x86)/Windows Kits/10/bin/10.0.19041.0/x64/fxc.exe';
const root=path.join(scratch,'hlsl'),art=path.join(root,'Art'),res=path.join(art,'Resources');
const shaders={'WorldKit.shader':art,'D6Pitch.shader':res,'D6Blob.shader':res,'D6Env.shader':res};
const variants=[[],['_MAIN_LIGHT_SHADOWS'],['_MAIN_LIGHT_SHADOWS','_SHADOWS_SOFT'],['_MAIN_LIGHT_SHADOWS','_SHADOWS_SOFT_MEDIUM'],['_MAIN_LIGHT_SHADOWS_CASCADE','_SHADOWS_SOFT_LOW']];
function program(source,name,folder,index,stage,keys){
  fs.copyFileSync(path.join(source,'D6Common.hlsl'),path.join(art,'D6Common.hlsl'));
  const text=fs.readFileSync(path.join(source,name),'utf8'),include=(text.match(/HLSLINCLUDE([\s\S]*?)ENDHLSL/)||[,''])[1];
  const programs=[...text.matchAll(/HLSLPROGRAM([\s\S]*?)ENDHLSL/g)].map(m=>m[1]);if(index>=programs.length)return null;
  const p=programs[index],entry=(p.match(new RegExp('#pragma\\s+'+(stage==='VERTEX'?'vertex':'fragment')+'\\s+(\\w+)'))||[])[1];if(!entry)return null;
  const file=path.join(folder,'legacy.hlsl'),pre=path.join(folder,'legacy.pre.hlsl'),out=path.join(scratch,'legacy.asm');
  fs.writeFileSync(file,['SHADER_API_D3D11 1','SHADER_TARGET 35','UNITY_VERSION 600060',`SHADER_STAGE_${stage} 1`,...keys.map(k=>k+' 1')].map(d=>'#define '+d).join('\n')+'\n'+include+'\n'+p.replace(/^\s*#pragma.*$/mg,''));
  let r=spawnSync(dxc,['-P',pre,'-I',root,file]);if(r.status!==0)return 'PREPROCESS FAILED';
  r=spawnSync(fxc,['/nologo','/Gec','/T',stage==='VERTEX'?'vs_5_0':'ps_5_0','/E',entry,'/Fc',out,pre],{encoding:'utf8'});if(r.status!==0)return 'COMPILE FAILED '+r.stderr;
  // Instructions and declarations only (no comments, file names or hashes).
  return fs.readFileSync(out,'utf8').split(/\r?\n/).filter(l=>l.trim()&&!l.trim().startsWith('//')).join('\n');
}
let same=0,different=0;
for(const [name,folder] of Object.entries(shaders))for(let index=0;index<2;index++)for(const stage of ['VERTEX','FRAGMENT'])for(const keys of variants){
  const a=program(head,name,folder,index,stage,keys),b=program(modified,name,folder,index,stage,keys);if(a===null&&b===null)continue;
  if(a===b)same++;else{different++;console.log(`DIFFERENT ${name} pass ${index} ${stage} [${keys.join(' ')}]`);}
}
console.log(`legacy programs identical to HEAD: ${same}, different: ${different}`);process.exit(different?1:0);
